import fs from'node:fs';import{createRequire}from'node:module';import{render,sample}from'./clock-v17.mjs';const sharp=createRequire(import.meta.url)(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/sharp');
const plate='data:image/png;base64,'+(await sharp(new URL('../v16/plate.webp',import.meta.url).pathname).png().toBuffer()).toString('base64'),mask='data:image/png;base64,'+fs.readFileSync(new URL('../v16/occlusion.png',import.meta.url)).toString('base64');
for(const variant of (process.argv[2]?[process.argv[2]]:['V16','A','B','C'])){for(const crop of ['full','ten','six','eleven','guides']){const s=render(sample,{variant,crop:crop==='guides'?'full':crop,guides:crop==='guides'}).replaceAll('../v16/plate.webp',plate).replaceAll('../v16/occlusion.png',mask);await sharp(Buffer.from(s)).resize(800,800,{fit:'contain',background:'#f4f5f4'}).flatten({background:'#f4f5f4'}).jpeg({quality:89}).toFile(new URL(`evidence/${variant}-${crop}.jpg`,import.meta.url).pathname);}
const s=render(sample,{variant});for(const m of s.matchAll(/<g data-main-number="(\d+)"[\s\S]*?<\/g>/g))await sharp(Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="-88 -100 1200 1200">${m[0]}</svg>`)).png().toFile(new URL(`evidence/${variant}-${m[1]}.png`,import.meta.url).pathname);}
